/// Seconds between the driver's lines (the wrist shows each for 8).
const BEAT_GAP: f32 = 7.0;
/// Before the first: the job's own lines go first (at the letter's
/// hand-in, four land at once).
const BEAT_FIRST: f32 = 12.0;

/// Tells the beats that open while you play: a job handed in at base that
/// finishes a rank, or the recall. The driver speaks a few seconds after
/// (the fitting's own line goes first), one line at a time, and hands his
/// gift back through the cab's hatch. A career loaded at a rank has heard its beats.
pub fn tell_beats(
    mut handover: MessageWriter<crate::raid::lev::HandOver>,
    progression: Option<Res<crate::progression::Progression>>,
    mut raid: ResMut<crate::raid::Raid>,
    time: Res<Time>,
    mut state: Local<(
        Option<(u32, bool)>,
        std::collections::VecDeque<&'static str>,
        f32,
    )>,
) {
    let tier = progression.map_or(0, |p| p.0.tier);
    let now = (tier, raid.recalled);
    let (seen, queue, timer) = &mut *state;
    let before = *seen.get_or_insert(now);
    if before != now {
        *seen = Some(now);
        for beat in BEATS {
            let at = |(tier, recalled): (u32, bool)| super::scenes::Standing {
                tier,
                recalled,
                visits: 0,
            };
            if beat.gate.open(at(now)) && !beat.gate.open(at(before)) {
                info!("story beat: {:?}", beat.gate);
                queue.extend(beat.radio.iter().copied());
                if let Some(id) = beat.gift {
                    // Passed back through the cab's hatch.
                    handover.write(crate::raid::lev::HandOver {
                        id: id.into(),
                        condition: 0.6,
                    });
                }
                *timer = BEAT_FIRST;
            }
        }
    }
    if queue.is_empty() {
        return;
    }
    *timer -= time.delta_secs();
    if *timer <= 0.0 {
        *timer = BEAT_GAP;
        if let Some(line) = queue.pop_front() {
            raid.say(line);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::render::screen::{MIN_EM_DEG, em_metres, read_from};
    use extraction_core::map::{MapDef, MarkerKind};

    fn map(name: &str) -> MapDef {
        let text = std::fs::read_to_string(
            crate::asset_root_path()
                .join("maps")
                .join(format!("{name}.ron")),
        )
        .unwrap();
        MapDef::from_ron(&text).unwrap()
    }

    /// The notes left in a map's staged scenes.
    fn scene_notes(map: &str) -> Vec<&'static crate::world::scenes::Note> {
        crate::world::scenes::of(map)
            .filter_map(|(_, s)| s.note.as_ref())
            .collect()
    }

    /// Every name a mention can point at in a map.
    fn places(name: &str, m: &MapDef) -> Vec<String> {
        let mut out: Vec<String> = m.markers.iter().map(|k| k.name.clone()).collect();
        out.extend(scene_notes(name).iter().map(|n| n.name.clone()));
        out.extend(m.regions.iter().map(|r| r.name.clone()));
        out.extend(m.roads.iter().map(|r| r.name.clone()));
        out.extend(m.water.iter().map(|w| w.name.clone()));
        out.extend(m.forests.iter().map(|f| f.name.clone()));
        out
    }

    fn worded<'a>(name: &str, m: &'a MapDef) -> Vec<&'a str> {
        m.markers
            .iter()
            .filter(|k| {
                matches!(
                    k.kind,
                    MarkerKind::Note { .. } | MarkerKind::Terminal { .. }
                )
            })
            .map(|k| k.name.as_str())
            .chain(scene_notes(name).iter().map(|n| n.name.as_str()))
            .collect()
    }

    /// Every note's and terminal page's letters are big enough to read
    /// at a metre (fast: straight from the maps, no app).
    #[test]
    fn every_note_fits_its_paper() {
        let mut small = Vec::new();
        for name in VALLEYS.iter().chain(&["training_yard"]) {
            let mut panels = crate::world::notes::marker_panels(&map(name));
            for n in scene_notes(name) {
                panels.push((n.name.clone(), crate::world::notes::note_panel(&n.text)));
            }
            for (what, panel) in panels {
                let deg = (em_metres(&panel) / read_from(&panel)).atan().to_degrees();
                if deg < MIN_EM_DEG {
                    small.push(format!("{name}: {what}: {deg:.2} deg"));
                }
            }
        }
        assert!(small.is_empty(), "too small to read:\n{}", small.join("\n"));
    }

    /// Terminal pages are laid out by hand: no wider than 32 columns or
    /// taller than 12 lines (`docs/LORE.md`, tone rules), which also keeps
    /// them clear of the CRT's own wrap.
    #[test]
    fn terminal_pages_keep_their_shape() {
        for s in crate::world::scenes::all() {
            let Some(t) = &s.terminal else {
                continue;
            };
            for page in t.pages.iter().chain(&t.recalled) {
                let lines = page.lines().count();
                let widest = page.lines().map(|l| l.chars().count()).max().unwrap_or(0);
                assert!(
                    lines <= 12 && widest <= 32,
                    "{}: {lines} lines, {widest} wide",
                    s.name
                );
            }
        }
        for name in VALLEYS {
            for m in &map(name).markers {
                let MarkerKind::Terminal { pages } = &m.kind else {
                    continue;
                };
                for (i, page) in pages.iter().enumerate() {
                    let lines = page.lines().count();
                    let widest = page.lines().map(|l| l.chars().count()).max().unwrap_or(0);
                    assert!(
                        lines <= 12 && widest <= 32,
                        "{name}: {} page {}: {lines} lines, {widest} wide",
                        m.name,
                        i + 1
                    );
                }
            }
        }
    }

    /// Every note and terminal is on the thread, every thread entry is in
    /// its map, and every place it names is there to be found.
    #[test]
    fn the_thread_points_at_real_places() {
        let maps: Vec<(&str, MapDef)> = VALLEYS.iter().map(|n| (*n, map(n))).collect();
        let get = |n: &str| &maps.iter().find(|(m, _)| *m == n).expect(n).1;
        let mut problems = Vec::new();
        for (name, m) in &maps {
            for note in worded(name, m) {
                let on = THREAD.iter().filter(|l| l.map == *name && l.note == note);
                if on.count() != 1 {
                    problems.push(format!("{name}: \"{note}\" isn't on the thread once"));
                }
            }
        }
        for lead in THREAD {
            if !worded(lead.map, get(lead.map)).contains(&lead.note) {
                problems.push(format!("{}: no note \"{}\"", lead.map, lead.note));
            }
            if lead.mentions.is_empty() {
                problems.push(format!("{}: \"{}\" names nowhere", lead.map, lead.note));
            }
            for (map, place) in lead.mentions {
                if !places(map, get(map)).iter().any(|p| p == place) {
                    problems.push(format!(
                        "{}: \"{}\" names {map}'s \"{place}\", which isn't there",
                        lead.map, lead.note
                    ));
                }
            }
        }
        assert!(problems.is_empty(), "{}", problems.join("\n"));
    }

    /// Each valley key is named by at least two notes, at least one of them
    /// in another valley: finding the words is how you find the keys.
    #[test]
    fn every_key_is_written_down_twice() {
        for name in VALLEYS {
            for m in &map(name).markers {
                if !matches!(m.kind, MarkerKind::ValleyKey { .. }) {
                    continue;
                }
                let by: Vec<&Lead> = THREAD
                    .iter()
                    .filter(|l| l.mentions.contains(&(name, m.name.as_str())))
                    .collect();
                assert!(by.len() >= 2, "{name}: {} named by {}", m.name, by.len());
                assert!(
                    by.iter().any(|l| l.map != name),
                    "{name}: {} named only in its own valley",
                    m.name
                );
            }
        }
    }

    /// The words themselves keep to the tone rules' few hard lines: no game
    /// terms on paper.
    #[test]
    fn no_game_words_in_the_zone() {
        const BANNED: [&str; 6] = ["loot", "quest", "spawn", "respawn", "hp", "xp"];
        for name in VALLEYS {
            let texts = map(name)
                .markers
                .iter()
                .filter_map(|m| Some((m.name.clone(), m.kind.text()?)))
                .chain(
                    scene_notes(name)
                        .iter()
                        .map(|n| (n.name.clone(), n.text.clone())),
                )
                .collect::<Vec<_>>();
            for (what, text) in texts {
                let lower = text.to_lowercase();
                for word in lower.split(|c: char| !c.is_alphanumeric()) {
                    assert!(!BANNED.contains(&word), "{name}: {what}: \"{word}\"");
                }
            }
        }
    }

    /// The arcs: every beat opens in order (Hana's on the ladder, the
    /// valleys' as you come back to them), each a scene with a note that
    /// names the beat before, Hana's last at the recall.
    #[test]
    fn every_beat_is_reachable_from_the_ladder_in_order() {
        use crate::world::scenes::Standing;
        use extraction_core::progression::{Progress, TIERS};
        // Climb the ladder as a career does, noting the ranks passed.
        let mut p = Progress::default();
        let mut ranks = vec![p.tier];
        while (p.tier as usize) < TIERS.len() {
            p.complete();
            if ranks.last() != Some(&p.tier) {
                ranks.push(p.tier);
            }
        }
        assert_eq!(ranks, (0..=TIERS.len() as u32).collect::<Vec<_>>());
        let at = |tier, recalled, visits| Standing {
            tier,
            recalled,
            visits,
        };
        let scenes = crate::world::scenes::all();
        let catalog =
            extraction_core::items::ItemCatalog::from_ron(extraction_core::items::BUILTIN_CATALOG)
                .unwrap();
        for thread in THREADS {
            let beats = thread.beats;
            assert!(
                beats.len() >= 3,
                "{}: a thread is three beats or more",
                thread.name
            );
            // The career moving on: for Hana's thread up the ladder, then the
            // recall; for a valley's, raid after raid there.
            let steps: Vec<Standing> = match thread.map {
                None => ranks
                    .iter()
                    .map(|r| at(*r, false, 0))
                    .chain([at(TIERS.len() as u32, true, 0)])
                    .collect(),
                Some(_) => (0..=12).map(|v| at(0, false, v)).collect(),
            };
            let mut opened = Vec::new();
            for step in &steps {
                for (i, b) in beats.iter().enumerate() {
                    if b.gate.open(*step) && !opened.contains(&i) {
                        opened.push(i);
                    }
                }
            }
            assert_eq!(
                opened,
                (0..beats.len()).collect::<Vec<_>>(),
                "{}: every beat opens, in order",
                thread.name
            );
            assert!(
                !beats[0].gate.open(steps[0]),
                "{}: nothing open before it starts",
                thread.name
            );
            if thread.map.is_none() {
                for (rank, b) in ranks.iter().skip(1).zip(beats) {
                    assert_eq!(b.gate, Gate::Tier(*rank), "one beat a rank");
                }
                assert_eq!(beats.last().unwrap().gate, Gate::Recalled);
                // The ladder's last job is the letter the third beat sets up.
                assert!(
                    beats
                        .iter()
                        .any(|b| b.gate == Gate::Tier(TIERS.len() as u32))
                );
                assert!(beats.iter().all(|b| !b.radio.is_empty()), "Lev tells each");
            }
            let mut previous: Vec<String> = vec![thread.from.into()];
            for b in beats {
                let mut notes = Vec::new();
                for name in b.scenes {
                    let s = scenes
                        .iter()
                        .find(|s| s.name == *name)
                        .unwrap_or_else(|| panic!("no scene {name}"));
                    assert_eq!(s.after, Some(b.gate), "{name} opens with its beat");
                    if let Some(map) = thread.map {
                        assert_eq!(s.map, map, "{name} is in its thread's valley");
                    }
                    if let Some(n) = &s.note {
                        notes.push(n.name.clone());
                    }
                }
                assert!(!notes.is_empty(), "{:?}: no note in the world", b.gate);
                // Pieced together, not told: each beat's note names the last.
                for n in &notes {
                    let lead = THREAD.iter().find(|l| l.note == n).expect(n);
                    assert!(
                        lead.mentions
                            .iter()
                            .any(|(_, m)| previous.iter().any(|p| p == m)),
                        "{n} doesn't lead on from {previous:?}"
                    );
                }
                previous = notes;
                if let Some(id) = b.gift {
                    assert!(catalog.kind(id).is_some(), "gift {id}");
                }
            }
        }
        // Every gated scene belongs to a beat.
        for s in scenes.iter().filter(|s| s.after.is_some()) {
            assert!(
                THREADS
                    .iter()
                    .flat_map(|t| t.beats)
                    .any(|b| b.scenes.contains(&s.name.as_str())),
                "{} is gated but on no beat",
                s.name
            );
        }
    }

    /// The letter's rank reached at base: the driver tells the beat on the
    /// radio, line by line, and leaves her photo in the stash.
    #[test]
    fn a_rank_reached_is_told_on_the_radio() {
        let opts = crate::LaunchOptions {
            robots: false,
            ..Default::default()
        };
        let mut app = crate::headless_app(opts, false);
        app.finish();
        app.cleanup();
        app.world_mut()
            .resource_mut::<crate::progression::Progression>()
            .0
            .tier = 3;
        for _ in 0..3 {
            app.update();
        }
        let photos = |app: &mut App| {
            let catalog = app.world().resource::<crate::items::Catalog>().clone();
            app.world_mut()
                .query::<&crate::items::Item>()
                .iter(app.world())
                .filter(|i| catalog.get(i.kind()).id == "old_photo")
                .count()
        };
        let before = photos(&mut app);
        app.world_mut()
            .resource_mut::<crate::progression::Progression>()
            .0
            .tier = 4;
        let beat = BEATS.iter().find(|b| b.gate == Gate::Tier(4)).unwrap();
        let mut heard = Vec::new();
        for _ in 0..3000 {
            app.update();
            let last = app
                .world()
                .resource::<crate::raid::Raid>()
                .log
                .last()
                .map(|l| l.0.clone());
            if let Some(l) = last
                && beat.radio.contains(&l.as_str())
                && heard.last() != Some(&l)
            {
                heard.push(l);
            }
            if heard.len() == beat.radio.len() {
                break;
            }
        }
        assert_eq!(heard, beat.radio, "said in order");
        assert_eq!(photos(&mut app), before + 1, "her photo in the stash");
    }
}
